questions.modelAnswer:
int secondLargest(int[] a) {
    int max = Integer.MIN_VALUE, second = Integer.MIN_VALUE;
    for (int x : a) {
        if (x > max) { second = max; max = x; }
        else if (x < max && x > second) { second = x; }
    }
    return second == Integer.MIN_VALUE ? -1 : second;
}

