    // your code here
}

questions.modelAnswer:
int countPermutations(String s) {
    int[] f = new int[256];
    for (char c : s.toCharArray()) f[c]++;
    int[] fact = new int[s.length() + 1]; fact[0] = 1;
    for (int i = 1; i <= s.length(); i++) fact[i] = fact[i - 1] * i;
    int r = fact[s.length()];
    for (int c : f) if (c > 1) r /= fact[c];
    return r;
}

