questions.modelAnswer:
int maxNonAdjacentSum(int[] a) {
    int inc = 0, exc = 0;
    for (int x : a) { int ni = exc + x; exc = Math.max(inc, exc); inc = ni; }
    return Math.max(inc, exc);
}
